Lemma art_secd_fin_facts : forall (Md : word -> option byte) sp raw t h ms x8 x9 x18 c88 c96,
  96 <= sp -> sp < 2 ^ 64 -> 0 <= t -> t + 4096 < 2 ^ 64 -> 0 <= h -> 0 <= ms -> h + ms <= sp - 96 ->
